/**
 * Conformance runner (SPEC §6): loads `conformance/scenarios/*.json`, runs the scenarios of the
 * selected categories against targets built by factories, and returns a report.
 *
 * ## Op handler contract (for category op files)
 *
 * Each category ships one file `src/testing/<category>-ops.ts` that exports a
 * {@link CategoryOps} object named `<category>Ops` (`coreOps`, `secretsOps`, `loggingOps`,
 * `tracingOps`) plus the target type its factory returns (`LoggingTarget`, `TracingTarget`).
 * `src/testing/ops.ts` wires the built-in files into {@link builtinOps} with `@sdk-kit:if`
 * blocks. Services can add or override ops at run time with {@link registerOps} or the
 * `ops` option of {@link runConformance}.
 *
 * A handler receives the target, the step `args` with every `${var}` already substituted
 * (`#{i}` is left for the handler), and an {@link OpContext}. It returns the op result; the
 * runner evaluates `expect` on it (or on the thrown error's `code` for `expect.error`) and
 * stores it under `save`.
 */

import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { checkExpectations, type Expectation } from "./expect.js";
import { builtinOps } from "./ops.js";

/** Scenario categories. */
export type Category = "core" | "secrets" | "logging" | "tracing";

/** One step of a scenario file. */
export interface ScenarioStep {
  op: string;
  args?: Record<string, unknown>;
  expect?: Expectation;
  save?: string;
  requires?: string[];
}

/** A scenario file (`spec/schemas/scenario.schema.json`). */
export interface Scenario {
  id: string;
  category: Category;
  description?: string;
  requires?: string[];
  batchOptions?: Record<string, unknown>;
  steps: ScenarioStep[];
}

/** Context passed to factories (one target per scenario). */
export interface FactoryContext {
  scenario: Scenario;
  /** Random 8-char lowercase run id (`${run}`). */
  run: string;
  /** Resolved provider prefix (`${prefix}`). */
  prefix: string;
  /** Scenario `batchOptions` (logging) for the factory to apply. */
  batchOptions?: Record<string, unknown>;
}

/** Builds a target for one scenario. */
export type Factory<T> = (context: FactoryContext) => T | Promise<T>;

/** Context passed to op handlers. */
export interface OpContext {
  readonly scenario: Scenario;
  readonly step: ScenarioStep;
  /** `${run}`. */
  readonly run: string;
  /** `${prefix}`. */
  readonly prefix: string;
  /** Variables (`${name}`): run, prefix, saved results, and values set by handlers. */
  readonly vars: Record<string, unknown>;
  /** Capabilities declared for this category. */
  readonly capabilities: ReadonlySet<string>;
  /** Replaces `${var}` placeholders in strings, recursively. */
  substitute<T>(value: T): T;
  /** Registers cleanup run after the scenario (in reverse order), even when it fails. */
  onCleanup(fn: () => unknown): void;
}

/** One op handler. */
export type OpHandler<T> = (
  target: T,
  args: Record<string, unknown>,
  context: OpContext,
) => unknown;

/** Handlers by op name. */
export type OpHandlers<T> = Readonly<Record<string, OpHandler<T>>>;

/** Everything the runner needs for one category. */
export interface CategoryOps<T> {
  ops: OpHandlers<T>;
  /** Called after each scenario (e.g. close the client). */
  dispose?: (target: T, context: OpContext) => unknown;
  /** Extra variables derived from the target (e.g. tracing `serviceName`). */
  variables?: (target: T) => Record<string, unknown>;
}

/** {@link CategoryOps} of any target type. */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type AnyOps = CategoryOps<any>;

const registry = new Map<string, AnyOps>();

/**
 * Adds or overrides op handlers for a category (merged over the built-in ones). Pass a
 * {@link CategoryOps} or plain handlers.
 */
export function registerOps<T>(category: string, ops: CategoryOps<T> | OpHandlers<T>): void {
  const normalized: CategoryOps<T> = isCategoryOps(ops) ? ops : { ops };
  const prev = registry.get(category);
  registry.set(category, prev === undefined ? normalized : mergeOps(prev, normalized));
}

/** Removes run-time registrations (tests). */
export function resetRegisteredOps(): void {
  registry.clear();
}

function isCategoryOps<T>(value: CategoryOps<T> | OpHandlers<T>): value is CategoryOps<T> {
  return (
    typeof (value as { ops?: unknown }).ops === "object" &&
    typeof (value as { ops?: unknown }).ops !== "function"
  );
}

function mergeOps(base: AnyOps, over: AnyOps): AnyOps {
  const merged: AnyOps = { ops: { ...base.ops, ...over.ops } };
  const dispose = over.dispose ?? base.dispose;
  const variables = over.variables ?? base.variables;
  if (dispose !== undefined) merged.dispose = dispose;
  if (variables !== undefined) merged.variables = variables;
  return merged;
}

/** Op handlers in effect for a category: built-ins, run-time registrations, then `extra`. */
export function resolveOps(
  category: string,
  extra?: Readonly<Record<string, AnyOps | OpHandlers<unknown>>>,
): AnyOps | undefined {
  let ops: AnyOps | undefined = (builtinOps as Readonly<Record<string, AnyOps | undefined>>)[
    category
  ];
  const registered = registry.get(category);
  if (registered !== undefined) ops = ops === undefined ? registered : mergeOps(ops, registered);
  const more = extra?.[category];
  if (more !== undefined) {
    const normalized: AnyOps = isCategoryOps(more) ? more : { ops: more };
    ops = ops === undefined ? normalized : mergeOps(ops, normalized);
  }
  return ops;
}

/** Factories by category (`core → client`, `secrets → SecretsProvider`, …). */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type ConformanceFactories = Partial<Record<Category, Factory<any>>>;

/** Options of {@link runConformance}. */
export interface ConformanceOptions {
  /** Directory with the scenario JSON files (`<repo>/conformance/scenarios`). */
  scenariosDir: string;
  /** Categories to run (default: every category with a factory). */
  categories?: readonly Category[];
  /** Target factories. */
  factories: ConformanceFactories;
  /** Declared capabilities: one list for all categories, or per category. */
  capabilities?: readonly string[] | Partial<Record<Category, readonly string[]>>;
  /** Provider prefix (default `grow-conformance/${run}/`; may contain `${run}`). */
  prefix?: string;
  /** Extra variables. */
  variables?: Record<string, unknown>;
  /** Run only these scenario ids. */
  only?: readonly string[];
  /** Extra op handlers by category. */
  ops?: Readonly<Record<string, AnyOps | OpHandlers<unknown>>>;
  /** Run-id generator (default: random 8 lowercase alphanumerics). */
  runId?: () => string;
}

/** Outcome of one step. */
export interface StepResult {
  index: number;
  op: string;
  status: "passed" | "failed" | "skipped";
  error?: string;
  skipReason?: string;
  durationMs: number;
}

/** Outcome of one scenario. */
export interface ScenarioResult {
  id: string;
  category: Category;
  status: "passed" | "failed" | "skipped";
  skipReason?: string;
  error?: string;
  steps: StepResult[];
  durationMs: number;
}

/** Report returned by {@link runConformance}. */
export interface ConformanceReport {
  ok: boolean;
  passed: number;
  failed: number;
  skipped: number;
  results: ScenarioResult[];
}

/** Random 8-char lowercase id. */
export function randomRunId(): string {
  const alphabet = "abcdefghijklmnopqrstuvwxyz0123456789";
  let out = "";
  for (let i = 0; i < 8; i++)
    out += alphabet[Math.floor(Math.random() * alphabet.length)] as string;
  return out;
}

/** Loads and sorts (by id) every scenario file in a directory. */
export function loadScenarios(scenariosDir: string): Scenario[] {
  const files = readdirSync(scenariosDir).filter((f) => f.endsWith(".json"));
  const scenarios = files.map((f) => {
    const parsed = JSON.parse(readFileSync(join(scenariosDir, f), "utf8")) as Scenario;
    if (
      typeof parsed.id !== "string" ||
      typeof parsed.category !== "string" ||
      !Array.isArray(parsed.steps)
    ) {
      throw new Error(`invalid scenario file ${f}`);
    }
    return parsed;
  });
  return scenarios.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
}

const VAR = /\$\{([A-Za-z_][A-Za-z0-9_]*)\}/g;
const WHOLE_VAR = /^\$\{([A-Za-z_][A-Za-z0-9_]*)\}$/;

/** Replaces `${name}` placeholders recursively. Unknown variables throw. */
export function substitute<T>(value: T, vars: Readonly<Record<string, unknown>>): T {
  const lookup = (name: string): unknown => {
    if (!(name in vars)) throw new Error(`unknown variable \${${name}}`);
    return vars[name];
  };
  const walk = (v: unknown): unknown => {
    if (typeof v === "string") {
      const whole = WHOLE_VAR.exec(v);
      if (whole !== null) return lookup(whole[1] as string);
      return v.replace(VAR, (_m, name: string) => String(lookup(name)));
    }
    if (Array.isArray(v)) return v.map(walk);
    if (v !== null && typeof v === "object") {
      return Object.fromEntries(
        Object.entries(v).map(([k, x]) => [
          k.replace(VAR, (_m, name: string) => String(lookup(name))),
          walk(x),
        ]),
      );
    }
    return v;
  };
  return walk(value) as T;
}

function capabilitySet(options: ConformanceOptions, category: Category): Set<string> {
  const caps = options.capabilities;
  if (caps === undefined) return new Set();
  if (Array.isArray(caps)) return new Set(caps as readonly string[]);
  return new Set((caps as Partial<Record<Category, readonly string[]>>)[category] ?? []);
}

function missing(requires: readonly string[] | undefined, caps: ReadonlySet<string>): string[] {
  return (requires ?? []).filter((r) => !caps.has(r));
}

function message(err: unknown): string {
  if (err instanceof Error) {
    const code = (err as { code?: unknown }).code;
    return typeof code === "string" ? `${code}: ${err.message}` : err.message;
  }
  return String(err);
}

/** Selected scenarios plus the reason a scenario is skipped up front (if any). */
export function planScenarios(
  options: ConformanceOptions,
): { scenario: Scenario; skipReason?: string }[] {
  const categories = new Set<string>(options.categories ?? Object.keys(options.factories));
  for (const c of categories) {
    if ((options.factories as Record<string, unknown>)[c] === undefined) {
      throw new Error(`conformance: no factory for category "${c}"`);
    }
  }
  return loadScenarios(options.scenariosDir)
    .filter((s) => categories.has(s.category))
    .filter((s) => options.only === undefined || options.only.includes(s.id))
    .map((scenario) => {
      const lacking = missing(scenario.requires, capabilitySet(options, scenario.category));
      return lacking.length > 0
        ? { scenario, skipReason: `missing capabilities: ${lacking.join(", ")}` }
        : { scenario };
    });
}

/** Runs one scenario. */
export async function runScenario(
  scenario: Scenario,
  options: ConformanceOptions,
): Promise<ScenarioResult> {
  const started = performance.now();
  const caps = capabilitySet(options, scenario.category);
  const result: ScenarioResult = {
    id: scenario.id,
    category: scenario.category,
    status: "passed",
    steps: [],
    durationMs: 0,
  };
  const lacking = missing(scenario.requires, caps);
  if (lacking.length > 0) {
    result.status = "skipped";
    result.skipReason = `missing capabilities: ${lacking.join(", ")}`;
    return result;
  }
  const category = resolveOps(scenario.category, options.ops);
  const factory = options.factories[scenario.category];
  if (category === undefined || factory === undefined) {
    result.status = "failed";
    result.error =
      category === undefined
        ? `no op handlers for category "${scenario.category}"`
        : `no factory for category "${scenario.category}"`;
    return result;
  }
  const run = (options.runId ?? randomRunId)();
  const vars: Record<string, unknown> = { ...options.variables, run };
  const prefix = substitute(options.prefix ?? "grow-conformance/${run}/", vars);
  vars.prefix = prefix;
  const cleanups: (() => unknown)[] = [];
  let currentStep: ScenarioStep = scenario.steps[0] ?? { op: "" };
  const context: OpContext = {
    scenario,
    get step() {
      return currentStep;
    },
    run,
    prefix,
    vars,
    capabilities: caps,
    substitute: <T>(v: T): T => substitute(v, vars),
    onCleanup: (fn) => {
      cleanups.push(fn);
    },
  };
  let target: unknown;
  try {
    target = await factory({
      scenario,
      run,
      prefix,
      ...(scenario.batchOptions === undefined ? {} : { batchOptions: scenario.batchOptions }),
    });
    Object.assign(vars, category.variables?.(target) ?? {}, { ...options.variables, run, prefix });
    for (const [index, step] of scenario.steps.entries()) {
      currentStep = step;
      const stepStart = performance.now();
      const stepResult: StepResult = { index, op: step.op, status: "passed", durationMs: 0 };
      result.steps.push(stepResult);
      const stepLacking = missing(step.requires, caps);
      if (stepLacking.length > 0) {
        stepResult.status = "skipped";
        stepResult.skipReason = `missing capabilities: ${stepLacking.join(", ")}`;
        continue;
      }
      try {
        const handler = category.ops[step.op];
        if (handler === undefined)
          throw new Error(`unknown op "${step.op}" for category ${scenario.category}`);
        const args = substitute(step.args ?? {}, vars);
        const expectation = step.expect === undefined ? undefined : substitute(step.expect, vars);
        let value: unknown;
        let thrown: unknown;
        let failed = false;
        try {
          value = await handler(target, args, context);
        } catch (err) {
          failed = true;
          thrown = err;
        }
        if (expectation?.error !== undefined) {
          if (!failed) throw new Error(`expected error ${expectation.error} but the op succeeded`);
          const code = (thrown as { code?: unknown }).code;
          if (code !== expectation.error) {
            throw new Error(`expected error ${expectation.error}, got ${message(thrown)}`);
          }
        } else {
          if (failed) throw thrown;
          if (expectation !== undefined) checkExpectations(value, expectation);
          if (step.save !== undefined) vars[step.save] = value;
        }
      } catch (err) {
        stepResult.status = "failed";
        stepResult.error = message(err);
        result.status = "failed";
        result.error = `step ${index} (${step.op}): ${stepResult.error}`;
        break;
      } finally {
        stepResult.durationMs = performance.now() - stepStart;
      }
    }
  } catch (err) {
    result.status = "failed";
    result.error = `setup: ${message(err)}`;
  } finally {
    if (target !== undefined && category.dispose !== undefined) {
      try {
        await category.dispose(target, context);
      } catch (err) {
        if (result.status !== "failed") {
          result.status = "failed";
          result.error = `dispose: ${message(err)}`;
        }
      }
    }
    for (const fn of cleanups.reverse()) {
      try {
        await fn();
      } catch {
        // cleanup failures never hide the scenario outcome
      }
    }
    result.durationMs = performance.now() - started;
  }
  return result;
}

/** Runs every selected scenario sequentially and returns the report. */
export async function runConformance(options: ConformanceOptions): Promise<ConformanceReport> {
  const results: ScenarioResult[] = [];
  for (const { scenario } of planScenarios(options)) {
    results.push(await runScenario(scenario, options));
  }
  const count = (s: ScenarioResult["status"]): number =>
    results.filter((r) => r.status === s).length;
  const failed = count("failed");
  return { ok: failed === 0, passed: count("passed"), failed, skipped: count("skipped"), results };
}

/** Human-readable report (one line per scenario, failures with their error). */
export function formatReport(report: ConformanceReport): string {
  const lines = report.results.map((r) => {
    const extra =
      r.status === "failed"
        ? ` — ${r.error ?? ""}`
        : r.status === "skipped"
          ? ` — ${r.skipReason ?? ""}`
          : "";
    const skippedSteps = r.steps
      .filter((s) => s.status === "skipped")
      .map((s) => `${s.op}#${s.index}`);
    const stepNote = skippedSteps.length > 0 ? ` (skipped steps: ${skippedSteps.join(", ")})` : "";
    return `${r.status.toUpperCase().padEnd(7)} ${r.id}${extra}${stepNote}`;
  });
  lines.push(`passed ${report.passed}, failed ${report.failed}, skipped ${report.skipped}`);
  return lines.join("\n");
}

/** Throws when the report has failures. */
export function assertConformance(report: ConformanceReport): void {
  if (!report.ok) throw new Error(`conformance failed:\n${formatReport(report)}`);
}

/** One scenario as a test case (see {@link conformanceCases}). */
export interface ConformanceCase {
  id: string;
  category: Category;
  /** Set when the scenario is skipped (missing capabilities). */
  skip?: string;
  /** Runs the scenario; throws on failure. */
  run(): Promise<ScenarioResult>;
}

/**
 * Test-framework helper: one case per selected scenario, loaded synchronously.
 *
 * ```ts
 * for (const c of conformanceCases(options)) it.skipIf(c.skip !== undefined)(c.id, () => c.run());
 * ```
 */
export function conformanceCases(options: ConformanceOptions): ConformanceCase[] {
  return planScenarios(options).map(({ scenario, skipReason }) => ({
    id: scenario.id,
    category: scenario.category,
    ...(skipReason === undefined ? {} : { skip: skipReason }),
    run: async () => {
      const result = await runScenario(scenario, options);
      if (result.status === "failed")
        throw new Error(`${scenario.id}: ${result.error ?? "failed"}`);
      return result;
    },
  }));
}
